<!-- 打印区域 -->
<div class="print-area" id="printArea"></div>

<script>
/* ============================================================
 * 数独引擎 SudokuEngine
 * ============================================================ */
class SudokuEngine {
  static CONFIG = {
    4: { rows: 4, cols: 4, subRows: 2, subCols: 2, maxVal: 4, label: '4×4' },
    6: { rows: 6, cols: 6, subRows: 2, subCols: 3, maxVal: 6, label: '6×6' },
    9: { rows: 9, cols: 9, subRows: 3, subCols: 3, maxVal: 9, label: '9×9' }
  };
  static DIFFICULTY = {
    easy:   { label: '简单', 4: 3,  6: 8,  9: 25 },
    medium: { label: '中等', 4: 5,  6: 13, 9: 38 },
    hard:   { label: '困难', 4: 7,  6: 18, 9: 48 }
  };
  generate(size, difficulty) {
    const config = SudokuEngine.CONFIG[size];
    const target = SudokuEngine.DIFFICULTY[difficulty][size];
    const solution = this._generateComplete(config);
    const puzzle = solution.map(row => [...row]);
    this._removeCells(puzzle, config, target);
    return { puzzle, solution };
  }
  _generateComplete(config) {
    const { rows, cols } = config;
    const board = Array.from({ length: rows }, () => new Array(cols).fill(0));
    this._fillBoard(board, config, 0);
    return board;
  }
  _fillBoard(board, config, index) {
    const { rows, cols } = config;
    if (index >= rows * cols) return true;
    const r = Math.floor(index / cols);
    const c = index % cols;
    if (board[r][c] !== 0) return this._fillBoard(board, config, index + 1);
    const nums = this._shuffle(Array.from({ length: config.maxVal }, (_, i) => i + 1));
    for (const num of nums) {
      if (this._isValid(board, config, r, c, num)) {
        board[r][c] = num;
        if (this._fillBoard(board, config, index + 1)) return true;
        board[r][c] = 0;
      }
    }
    return false;
  }
  _isValid(board, config, row, col, num) {
    const { rows, cols, subRows, subCols } = config;
    for (let c = 0; c < cols; c++) { if (board[row][c] === num) return false; }
    for (let r = 0; r < rows; r++) { if (board[r][col] === num) return false; }
    const br = Math.floor(row / subRows) * subRows;
    const bc = Math.floor(col / subCols) * subCols;
    for (let r = br; r < br + subRows; r++) {
      for (let c = bc; c < bc + subCols; c++) { if (board[r][c] === num) return false; }
    }
    return true;
  }
  _removeCells(puzzle, config, target) {
    const { rows, cols } = config;
    const positions = [];
    for (let r = 0; r < rows; r++) { for (let c = 0; c < cols; c++) { positions.push([r, c]); } }
    this._shuffle(positions);
    let removed = 0;
    for (const [r, c] of positions) {
      if (removed >= target) break;
      const saved = puzzle[r][c];
      puzzle[r][c] = 0;
      if (this._hasUniqueSolution(puzzle, config)) { removed++; }
      else { puzzle[r][c] = saved; }
    }
  }
  _hasUniqueSolution(board, config) {
    const copy = board.map(row => [...row]);
    return this._countSolutions(copy, config, 2) === 1;
  }
  _countSolutions(board, config, limit) {
    const { rows, cols, maxVal } = config;
    let count = 0;
    const solve = (index) => {
      if (count >= limit) return;
      if (index >= rows * cols) { count++; return; }
      const r = Math.floor(index / cols);
      const c = index % cols;
      if (board[r][c] !== 0) { solve(index + 1); return; }
      for (let num = 1; num <= maxVal; num++) {
        if (this._isValid(board, config, r, c, num)) {
          board[r][c] = num; solve(index + 1); board[r][c] = 0;
          if (count >= limit) return;
        }
      }
    };
    solve(0);
    return count;
  }
  _shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  }
}

/* ============================================================
 * 打印管理器 PrintManager
 * ============================================================ */
class PrintManager {
  constructor() {
    this.queue = [];
    this.container = document.getElementById('printArea');
    this.onUpdate = null;
    this._puzzlesPerPage = 6;
  }
  setPuzzlesPerPage(n) { this._puzzlesPerPage = Math.max(1, Math.min(6, parseInt(n,10)||6)); }
  add(p) { this.queue.push(p); if (this.onUpdate) this.onUpdate(this.queue.length); }
  addMultiple(items) { this.queue.push(...items); if (this.onUpdate) this.onUpdate(this.queue.length); }
  clear() { this.queue = []; if (this.onUpdate) this.onUpdate(0); }
  getCount() { return this.queue.length; }
  print() {
    if (this.queue.length === 0) { alert('打印队列为空，请先生成题目。'); return; }
    this._render(); setTimeout(() => { window.print(); }, 50);
  }
  _render() {
    const pieces = [...this.queue];
    const perPage = Math.min(this._puzzlesPerPage, 6);
    let cols, rows;
    if (perPage === 1)      { cols = 1; rows = 1; }
    else if (perPage === 2) { cols = 1; rows = 2; }
    else if (perPage === 3) { cols = 1; rows = 3; }
    else if (perPage <= 4)  { cols = 2; rows = 2; }
    else                    { cols = 2; rows = 3; }
    const PAGE_W = 180, PAGE_H = 260, GAP = 3, LABEL_H = 7;
    const maxSize = Math.max(...pieces.map(p => p.size));
    const maxCellW = (PAGE_W - (cols-1)*GAP) / cols / maxSize;
    const maxCellH = (PAGE_H - rows*LABEL_H - (rows-1)*GAP) / rows / maxSize;
    const cellSize = Math.floor(Math.min(maxCellW, maxCellH) * 10) / 10;
    const fontSize = Math.max(7, Math.round(cellSize * 0.85));
    let html = '';
    for (let i = 0; i < pieces.length; i += perPage) {
      html += '<div class="print-page">';
      const pagePieces = pieces.slice(i, i + perPage);
      for (let j = 0; j < pagePieces.length; j += cols) {
        html += '<div class="print-row">';
        const rowPieces = pagePieces.slice(j, j + cols);
        for (let k = 0; k < rowPieces.length; k++) {
          html += this._renderPuzzleHTML(i+j+k+1, rowPieces[k], cellSize, fontSize);
        }
        const padSize = rowPieces.length > 0 ? rowPieces[0].size : maxSize;
        for (let k = rowPieces.length; k < cols; k++) {
          html += '<div class="print-puzzle" style="visibility:hidden;width:' + (cellSize*padSize) + 'mm"></div>';
        }
        html += '</div>';
      }
      html += '</div>';
    }
    this.container.innerHTML = html;
  }
  _renderPuzzleHTML(index, data, cellSize, fontSize) {
    const { size, difficulty, puzzle } = data;
    const config = SudokuEngine.CONFIG[size];
    const diffLabel = SudokuEngine.DIFFICULTY[difficulty].label;
    return '<div class="print-puzzle"><div class="print-puzzle-label">第 ' + index + ' 题 · ' + config.label + ' · ' + diffLabel + '</div>' + this._renderGridHTML(puzzle, size, cellSize, fontSize) + '</div>';
  }
  _renderGridHTML(board, size, cellSize, fontSize) {
    const config = SudokuEngine.CONFIG[size];
    const { rows, cols, subRows, subCols } = config;
    const cellMM = cellSize + 'mm';
    const fSize = fontSize + 'pt';
    let html = '<div class="sudoku-grid size-' + size + '" style="grid-template-columns:repeat(' + cols + ',' + cellMM + ')">';
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const val = board[r][c];
        const valStr = val !== 0 ? val : '';
        const classes = ['cell'];
        if (val !== 0) classes.push('given'); else classes.push('empty');
        if ((c+1) % subCols === 0 && c+1 < cols) classes.push('br');
        if ((r+1) % subRows === 0 && r+1 < rows) classes.push('bb');
        html += '<div class="' + classes.join(' ') + '" style="width:' + cellMM + ';height:' + cellMM + ';font-size:' + fSize + '">' + valStr + '</div>';
      }
    }
    html += '</div>';
    return html;
  }
}

/* ============================================================
 * 应用主逻辑 App
 * ============================================================ */
const App = {
  engine: new SudokuEngine(),
  printManager: new PrintManager(),
  currentData: null,
  els: {},
  init() {
    this.els = {
      sizeSelect: document.getElementById('sizeSelect'),
      diffSelect: document.getElementById('diffSelect'),
      perPageSelect: document.getElementById('perPageSelect'),
      btnGenerate: document.getElementById('btnGenerate'),
      btnGenerateMany: document.getElementById('btnGenerateMany'),
      btnPrint: document.getElementById('btnPrint'),
      btnClear: document.getElementById('btnClear'),
      puzzleLabel: document.getElementById('puzzleLabel'),
      gridContainer: document.getElementById('puzzleGridContainer'),
      queueCount: document.getElementById('queueCount'),
      loadingOverlay: document.getElementById('loadingOverlay'),
    };
    this.printManager.onUpdate = (count) => { this.els.queueCount.textContent = count; };
    this.printManager.setPuzzlesPerPage(parseInt(this.els.perPageSelect.value, 10));
    this.els.perPageSelect.addEventListener('change', () => {
      this.printManager.setPuzzlesPerPage(parseInt(this.els.perPageSelect.value, 10));
    });
    this.els.btnGenerate.addEventListener('click', () => this.generateOne());
    this.els.btnGenerateMany.addEventListener('click', () => this.generateMany(6));
    this.els.btnPrint.addEventListener('click', () => this.printManager.print());
    this.els.btnClear.addEventListener('click', () => this.clearAll());
    this.generateOne();
  },
  generateOne() {
    const size = parseInt(this.els.sizeSelect.value, 10);
    const difficulty = this.els.diffSelect.value;
    this._showLoading(true);
    setTimeout(() => {
      try {
        const result = this.engine.generate(size, difficulty);
        this.currentData = { size, difficulty, puzzle: result.puzzle };
        this._renderOnScreen(this.currentData);
        this.printManager.add(this.currentData);
      } catch (e) { console.error('生成失败:', e); alert('题目生成失败，请重试。');
      } finally { this._showLoading(false); }
    }, 30);
  },
  generateMany(count) {
    const size = parseInt(this.els.sizeSelect.value, 10);
    const difficulty = this.els.diffSelect.value;
    this._showLoading(true);
    setTimeout(() => {
      try {
        const items = []; let lastResult = null;
        for (let i = 0; i < count; i++) {
          const result = this.engine.generate(size, difficulty);
          items.push({ size, difficulty, puzzle: result.puzzle });
          lastResult = result;
        }
        this.currentData = { size, difficulty, puzzle: lastResult.puzzle };
        this._renderOnScreen(this.currentData);
        this.printManager.addMultiple(items);
      } catch (e) { console.error('批量生成失败:', e); alert('批量生成失败，请重试。');
      } finally { this._showLoading(false); }
    }, 30);
  },
  clearAll() { this.printManager.clear(); },
  _renderOnScreen(data) {
    const { size, difficulty, puzzle } = data;
    const config = SudokuEngine.CONFIG[size];
    const diffLabel = SudokuEngine.DIFFICULTY[difficulty].label;
    this.els.puzzleLabel.textContent = config.label + ' · ' + diffLabel;
    this.els.gridContainer.innerHTML = this.printManager._renderGridHTML(puzzle, size, 'screen');
  },
  _showLoading(active) { this.els.loadingOverlay.classList.toggle('active', active); }
};
document.addEventListener('DOMContentLoaded', () => { App.init(); });
