![img](https://cdn-cf.cayzlh.com/2020/05/10/gEeFMx.jpg)

(此图来自《Spring 揭秘》) `Spring IOC`容器所起的作用如上图所示，它会以某种方式加载 `Configuration Metadata`，将其解析注册到容器内部，然后回根据这些信息绑定整个系统的对象，最终组装成一个可用的基于轻量级容器的应用系统。

 `Spring` 在实现上述功能中，将整个流程分为两个阶段：**容器初始化阶段**和**加载bean 阶段**。

- **容器初始化阶段**：首先通过某种方式加载 Configuration Metadata (主要是依据 Resource、ResourceLoader 两个体系)，然后容器会对加载的 Configuration MetaData 进行解析和分析，并将分析的信息组装成 BeanDefinition，并将其保存注册到相应的 BeanDefinitionRegistry 中。至此，Spring IOC 的初始化工作完成。
- **加载 bean 阶段**：经过容器初始化阶段后，应用程序中定义的 bean 信息已经全部加载到系统中了，当我们显示或者隐式地调用 `getBean()` 时，则会触发加载 bean 阶段。在这阶段，容器会首先检查所请求的对象是否已经初始化完成了，如果没有，则会根据注册的 bean 信息实例化请求的对象，并为其注册依赖，然后将其返回给请求方。至此第二个阶段也已经完成。

当我们显示或者隐式地调用 `getBean()` 时，则会触发加载 `bean` 阶段。如下：

```java
public Object getBean(String name) throws BeansException {
  return doGetBean(name, null, null, false);
}
```

内部调用 `doGetBean()` 方法，其接受四个参数：

- **name**：要获取 bean 的名字
- **requiredType**：要获取 bean 的类型
- **args**：创建 bean 时传递的参数。这个参数仅限于创建 bean 时使用
- **typeCheckOnly**：是否为类型检查

这个方法的代码比较长，各位耐心看下：

```java
protected <T> T doGetBean(
  final String name, @Nullable final Class<T> requiredType,
  @Nullable final Object[] args, boolean typeCheckOnly) throws BeansException {

  // 获取 beanName，这里是一个转换动作，将 name 转换Wie beanName
  final String beanName = transformedBeanName(name);
  Object bean;

  // 从缓存中或者实例工厂中获取 bean
  // *** 这里会涉及到解决循环依赖 bean 的问题
  Object sharedInstance = getSingleton(beanName);
  if (sharedInstance != null && args == null) {
    if (logger.isDebugEnabled()) {
      if (isSingletonCurrentlyInCreation(beanName)) {
        logger.debug("Returning eagerly cached instance of singleton bean '" 
         + beanName 
         +
        "' that is not fully initialized yet - a consequence of a circular reference");
      }
      else {
        logger.debug("Returning cached instance of singleton bean '" + beanName + "'");
      }
    }
    bean = getObjectForBeanInstance(sharedInstance, name, beanName, null);
  }

  else {

    // 因为 Spring 只解决单例模式下得循环依赖，在原型模式下如果存在循环依赖则会抛出异常
    // **关于循环依赖后续会单独出文详细说明**
    if (isPrototypeCurrentlyInCreation(beanName)) {
      throw new BeanCurrentlyInCreationException(beanName);
    }

    // 如果容器中没有找到，则从父类容器中加载
    BeanFactory parentBeanFactory = getParentBeanFactory();
    if (parentBeanFactory != null && !containsBeanDefinition(beanName)) {
      String nameToLookup = originalBeanName(name);
      if (parentBeanFactory instanceof AbstractBeanFactory) {
        return ((AbstractBeanFactory) parentBeanFactory).doGetBean(
          nameToLookup, requiredType, args, typeCheckOnly);
      }
      else if (args != null) {
        return (T) parentBeanFactory.getBean(nameToLookup, args);
      }
      else {
        return parentBeanFactory.getBean(nameToLookup, requiredType);
      }
    }

    // 如果不是仅仅做类型检查则是创建bean，这里需要记录
    if (!typeCheckOnly) {
      markBeanAsCreated(beanName);
    }

    try {
      // 从容器中获取 beanName 相应的 GenericBeanDefinition，并将其转换为 RootBeanDefinition
      final RootBeanDefinition mbd = getMergedLocalBeanDefinition(beanName);

      // 检查给定的合并的 BeanDefinition
      checkMergedBeanDefinition(mbd, beanName, args);

      // 处理所依赖的 bean
      String[] dependsOn = mbd.getDependsOn();
      if (dependsOn != null) {
        for (String dep : dependsOn) {
          // 若给定的依赖 bean 已经注册为依赖给定的b ean
          // 循环依赖的情况
          if (isDependent(beanName, dep)) {
            throw new BeanCreationException(
              mbd.getResourceDescription(), 
              beanName,

              "Circular depends-on relationship between '" 
              + beanName + "' and '" + dep + "'");
          }
          // 缓存依赖调用
          registerDependentBean(dep, beanName);
          try {
            getBean(dep);
          }
          catch (NoSuchBeanDefinitionException ex) {
            throw new BeanCreationException(
              mbd.getResourceDescription(), 
              beanName,

              "'" + beanName 
              + "' depends on missing bean '" + dep + "'", ex);
          }
        }
      }

      // bean 实例化
      // 单例模式
      if (mbd.isSingleton()) {
        sharedInstance = getSingleton(beanName, () -> {
          try {
            return createBean(beanName, mbd, args);
          }
          catch (BeansException ex) {
            // 显示从单利缓存中删除 bean 实例
            // 因为单例模式下为了解决循环依赖，可能他已经存在了，所以销毁它
            destroySingleton(beanName);
            throw ex;
          }
        });
        bean = getObjectForBeanInstance(sharedInstance, name, beanName, mbd);
      }

      // 原型模式
      else if (mbd.isPrototype()) {
        // It's a prototype -> create a new instance.
        Object prototypeInstance = null;
        try {
          beforePrototypeCreation(beanName);
          prototypeInstance = createBean(beanName, mbd, args);
        }
        finally {
          afterPrototypeCreation(beanName);
        }
        bean = getObjectForBeanInstance(prototypeInstance, name, beanName, mbd);
      }

      else {
        // 从指定的 scope 下创建 bean
        String scopeName = mbd.getScope();
        final Scope scope = this.scopes.get(scopeName);
        if (scope == null) {
          throw new IllegalStateException(
            "No Scope registered for scope name '" + scopeName + "'");
        }
        try {
          Object scopedInstance = scope.get(beanName, () -> {
            beforePrototypeCreation(beanName);
            try {
              return createBean(beanName, mbd, args);
            }
            finally {
              afterPrototypeCreation(beanName);
            }
          });
          bean = getObjectForBeanInstance(scopedInstance, name, beanName, mbd);
        }
        catch (IllegalStateException ex) {
          throw new BeanCreationException(
            beanName,

            "Scope '" + scopeName 
            + "' is not active for the current thread; consider " 
            + "defining a scoped proxy for this bean if you intend to refer to it from a singleton",

            ex);
        }
      }
    }
    catch (BeansException ex) {
      cleanupAfterBeanCreationFailure(beanName);
      throw ex;
    }
  }

  // 检查需要的类型是否符合 bean 的实际类型
  if (requiredType != null && !requiredType.isInstance(bean)) {
    try {
      T convertedBean = getTypeConverter().convertIfNecessary(bean, requiredType);
      if (convertedBean == null) {
        throw new BeanNotOfRequiredTypeException(name, requiredType, bean.getClass());
      }
      return convertedBean;
    }
    catch (TypeMismatchException ex) {
      if (logger.isDebugEnabled()) {
        logger.debug("Failed to convert bean '" + name + "' to required type '" +
                     ClassUtils.getQualifiedName(requiredType) + "'", ex);
      }
      throw new BeanNotOfRequiredTypeException(name, requiredType, bean.getClass());
    }
  }
  return (T) bean;
}
