deploy_Rollback()  
{  
	#进入备份文件夹  
    cd ${mainpath}/backup/  
    #获取最新备份文件  
    file_name_new=''  
    for i in `ls -tr`;  
    do  
        echo $i;  
        file_name_new=$i;  
    done;  
    #将备份文件复制到webapps  
    cp  ${mainpath}/backup/${file_name_new} ${mainpath}/${appName}.jar 
    if [ $? -eq 0 ]  
    then  
        echo 复制${file_name_new}成功  
    else  
        echo 复制失败，退出！  
    exit 1  
    fi  
    #进入webapps/目录  
    cd  ${mainpath}
